"""Unified 5-method analysis with Table 7 consistent parameters.

Key change from 5method_leadlag.json:
- Threshold onset: 2-sigma (Table 7) instead of 3-sigma
- All params: n_perm=5000, xcorr_lag=5, granger_lag=1, alpha=0.05
"""
import json, os, sys, time
import numpy as np
from scipy import stats
from statsmodels.tsa.stattools import adfuller

sys.path.insert(0, "/root/autodl-tmp/distrib_canary_collapse")
from permutation_granger import permutation_granger_test

N_PERM = 5000
ALPHA = 0.05
XCORR_LAG = 5
GRANGER_LAG = 1
THRESHOLD_SIGMA = 2.0

CANARIES = ["token_entropy", "ece"]
DOWNSTREAMS = ["distinct_1", "distinct_2", "distinct_3", "perplexity"]
PAIRS = [(c, d) for c in CANARIES for d in DOWNSTREAMS]
HIGHER_IS_WORSE = {"ece", "perplexity"}
LOWER_IS_WORSE = {"token_entropy", "distinct_1", "distinct_2", "distinct_3"}

BASE = "/root/autodl-tmp/distrib_canary_collapse"
OUTPUT_DIR = os.path.join(BASE, "artifacts", "mmct_results", "unified_data")

CONDITIONS = {
    "a000_s42": os.path.join(BASE, "results/alpha_sweep/a000_s42"),
    "a000_s43": os.path.join(BASE, "results/alpha_sweep/a000_s43"),
    "a000_s44": os.path.join(BASE, "results/alpha_sweep/a000_s44"),
    "a025_s43": os.path.join(BASE, "results/alpha_sweep/a025_s43"),
    "a025_s44": os.path.join(BASE, "results/alpha_sweep/a025_s44"),
    "a050_s42": os.path.join(BASE, "results/alpha_sweep/a050_s42"),
    "a050_s43": os.path.join(BASE, "results/alpha_sweep/a050_s43"),
    "a050_s44": os.path.join(BASE, "results/alpha_sweep/a050_s44"),
    "a075_s42": os.path.join(BASE, "results/alpha_sweep/a075_s42"),
    "a075_s43": os.path.join(BASE, "results/alpha_sweep/a075_s43"),
    "a075_s44": os.path.join(BASE, "results/alpha_sweep/a075_s44"),
    "pythia410m_wiki_a100_s42": os.path.join(BASE, "results/generalize/pythia410m_wiki_a100_s42"),
    "gpt2m_wiki_a100_s42": os.path.join(BASE, "results/generalize/gpt2m_wiki_a100_s42"),
    "opt1b_wiki_a100_s42": os.path.join(BASE, "results/generalize/opt1b_wiki_a100_s42"),
    "pythia14b_wiki_a100_s42": os.path.join(BASE, "results/generalize/pythia14b_wiki_a100_s42"),
    "pythia14b_wiki_a100_s43": os.path.join(BASE, "results/generalize/pythia14b_wiki_a100_s43"),
    "pythia1b_c4_a100_s42": os.path.join(BASE, "results/generalize/pythia1b_c4_a100_s42"),
    "pythia1b_c4_a100_s43": os.path.join(BASE, "results/generalize/pythia1b_c4_a100_s43"),
}


def load_series(data_dir):
    with open(os.path.join(data_dir, "all_metrics.json")) as f:
        data = json.load(f)
    data.sort(key=lambda x: x["generation"])
    return {k: np.array([d[k] for d in data]) for k in CANARIES + DOWNSTREAMS}, len(data)


def orient(series, name):
    return -series.copy() if name in LOWER_IS_WORSE else series.copy()


def naive_xcorr(c, d, cn, dn):
    x, y = orient(c, cn), orient(d, dn)
    n = len(x)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-XCORR_LAG, XCORR_LAG + 1):
        if lag >= 0:
            a, b = x[lag:], y[:n - lag]
        else:
            a, b = x[:n + lag], y[-lag:]
        if len(a) < 4:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {"significant": bool(best_p < ALPHA), "peak_lag": int(best_lag),
            "r": round(float(best_r), 4), "p_value": round(float(best_p), 6)}


def diff_xcorr(c, d, cn, dn):
    dx, dy = np.diff(orient(c, cn)), np.diff(orient(d, dn))
    n = len(dx)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-XCORR_LAG, XCORR_LAG + 1):
        if lag >= 0:
            a, b = dx[lag:], dy[:n - lag]
        else:
            a, b = dx[:n + lag], dy[-lag:]
        if len(a) < 4:
            continue
        if np.std(a) < 1e-12 or np.std(b) < 1e-12:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {"significant": bool(best_p < ALPHA), "peak_lag": int(best_lag),
            "r": round(float(best_r), 4), "p_value": round(float(best_p), 6)}


def _onset_gen(series, name):
    s = orient(series, name)
    mu = s[0]
    sigma = np.std(s[:3]) if len(s) >= 3 else np.std(s)
    if sigma < 1e-12:
        sigma = np.std(s) if np.std(s) > 1e-12 else 1.0
    for i in range(1, len(s)):
        if abs(s[i] - mu) >= THRESHOLD_SIGMA * sigma:
            return i
    return None


def threshold_onset(c, d, cn, dn):
    c_onset, d_onset = _onset_gen(c, cn), _onset_gen(d, dn)
    if c_onset is not None and d_onset is not None:
        lead = d_onset - c_onset
        sig = lead > 0
    else:
        lead, sig = None, False
    return {"significant": sig, "canary_onset": c_onset,
            "downstream_onset": d_onset, "lead_time": lead,
            "threshold": f"{THRESHOLD_SIGMA}x_sigma_drift"}


def perm_granger(c, d, cn, dn, seed=42):
    x, y = orient(c, cn), orient(d, dn)
    r = permutation_granger_test(x, y, max_lag=GRANGER_LAG, n_perm=N_PERM,
                                  seed=seed, difference=True)
    p = r.get("p_value")
    return {"significant": bool(p is not None and p < ALPHA),
            "f_stat": round(float(r["f_stat"]), 4) if r["f_stat"] is not None else None,
            "p_value": round(float(p), 6) if p is not None else None,
            "n_perm": N_PERM}


def ty_granger(c, d, cn, dn):
    x, y = orient(c, cn), orient(d, dn)
    T = len(x)

    def get_d(s):
        if len(s) < 6:
            return 0
        try:
            if adfuller(s, maxlag=min(2, len(s)//3-1), regression='c', autolag=None)[1] < 0.05:
                return 0
            d1 = np.diff(s)
            if len(d1) < 6:
                return 1
            if adfuller(d1, maxlag=min(2, len(d1)//3-1), regression='c', autolag=None)[1] < 0.05:
                return 1
            return 2
        except Exception:
            return 1

    d_max = max(get_d(x), get_d(y))
    k = GRANGER_LAG
    p_order = k + d_max
    n = T - p_order
    if n < p_order + 3:
        return {"significant": False, "wald_F": None, "p_value": None,
                "d_max": int(d_max), "k": k, "note": f"T={T},p={p_order},n={n}"}

    Y = y[p_order:]
    cols = [np.ones(n)]
    for lag in range(1, p_order + 1):
        cols.append(y[p_order - lag:T - lag])
    x_start = len(cols)
    for lag in range(1, p_order + 1):
        cols.append(x[p_order - lag:T - lag])
    X = np.column_stack(cols)

    try:
        beta = np.linalg.lstsq(X, Y, rcond=None)[0]
        resid = Y - X @ beta
        df_resid = n - X.shape[1]
        if df_resid <= 0:
            return {"significant": False, "wald_F": None, "p_value": None,
                    "d_max": int(d_max), "k": k, "note": f"df_resid={df_resid}"}
        sigma2 = np.sum(resid**2) / df_resid
        R = np.zeros((k, X.shape[1]))
        for i in range(k):
            R[i, x_start + i] = 1.0
        XtX_inv = np.linalg.inv(X.T @ X)
        Rb = R @ beta
        wald = float(Rb.T @ np.linalg.inv(R @ XtX_inv @ R.T * sigma2) @ Rb) / k
        p_val = 1.0 - stats.f.cdf(wald, k, df_resid)
    except Exception as e:
        return {"significant": False, "wald_F": None, "p_value": None,
                "d_max": int(d_max), "k": k, "note": str(e)}

    return {"significant": bool(p_val < ALPHA), "wald_F": round(float(wald), 4),
            "p_value": round(float(p_val), 6), "d_max": int(d_max), "k": k,
            "df_resid": int(df_resid)}


METHODS = [
    ("naive_xcorr", naive_xcorr),
    ("diff_xcorr", diff_xcorr),
    ("threshold_onset", threshold_onset),
    ("perm_granger", perm_granger),
    ("ty_granger", ty_granger),
]


def analyze_pair(c, d, cn, dn, seed):
    fwd, rev = {}, {}
    for name, func in METHODS:
        if name == "perm_granger":
            fwd[name] = func(c, d, cn, dn, seed=seed)
            rev[name] = func(d, c, dn, cn, seed=seed)
        else:
            fwd[name] = func(c, d, cn, dn)
            rev[name] = func(d, c, dn, cn)
    consensus = sum(1 for m in fwd.values() if m.get("significant", False))
    return fwd, rev, consensus


def analyze_condition(name, data_dir, seed=42):
    series, n_gens = load_series(data_dir)
    result = {
        "condition": name, "data_dir": data_dir, "n_generations": n_gens,
        "params": {
            "n_perm": N_PERM, "xcorr_lag": XCORR_LAG,
            "granger_lag": GRANGER_LAG,
            "threshold_sigma": THRESHOLD_SIGMA, "alpha": ALPHA,
        },
        "methods": ["naive_xcorr", "diff_xcorr", "threshold_onset",
                     "perm_granger", "ty_granger"],
        "pairs": [],
    }
    for cn, dn in PAIRS:
        fwd, rev, consensus = analyze_pair(series[cn], series[dn], cn, dn, seed)
        result["pairs"].append({
            "canary": cn, "downstream": dn,
            "forward": fwd, "reverse": rev, "consensus": consensus,
        })
    return result


def load_old_results(data_dir):
    path = os.path.join(data_dir, "analysis", "5method_leadlag.json")
    if os.path.exists(path):
        with open(path) as f:
            return json.load(f)
    return None


def compare_results(old, new, cond_name):
    if old is None:
        return {"condition": cond_name, "status": "no_old_data", "n_changes": 0, "changes": []}
    diffs = []
    for new_pair in new["pairs"]:
        cn, dn = new_pair["canary"], new_pair["downstream"]
        old_pair = None
        for op in old.get("pairs", []):
            if op.get("canary") == cn and op.get("downstream") == dn:
                old_pair = op
                break
            fwd = op.get("forward", {})
            if fwd.get("canary") == cn and fwd.get("downstream") == dn:
                old_pair = op
                break
        if old_pair is None:
            continue
        old_fwd = old_pair.get("forward", {})
        new_fwd = new_pair["forward"]
        for method in ["naive_xcorr", "diff_xcorr", "threshold_onset", "perm_granger", "ty_granger"]:
            old_sig = old_fwd.get(method, {}).get("significant", False)
            new_sig = new_fwd.get(method, {}).get("significant", False)
            if old_sig != new_sig:
                diffs.append({
                    "pair": f"{cn}->{dn}", "method": method,
                    "old_significant": old_sig, "new_significant": new_sig,
                    "old_detail": old_fwd.get(method, {}),
                    "new_detail": new_fwd.get(method, {}),
                })
    return {"condition": cond_name, "n_changes": len(diffs), "changes": diffs}


def main():
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    t0 = time.time()
    results = {}
    comparisons = []

    for name, data_dir in sorted(CONDITIONS.items()):
        if not os.path.exists(os.path.join(data_dir, "all_metrics.json")):
            print(f"SKIP: {name}")
            continue
        seed = 43 if "_s43" in name else (44 if "_s44" in name else 42)
        print(f"Analyzing {name} (seed={seed})...", end=" ", flush=True)
        t1 = time.time()
        result = analyze_condition(name, data_dir, seed)
        dt = time.time() - t1
        out_path = os.path.join(OUTPUT_DIR, f"{name}.json")
        with open(out_path, 'w') as f:
            json.dump(result, f, indent=2)
        counts = {}
        for m in ["naive_xcorr", "diff_xcorr", "threshold_onset", "perm_granger", "ty_granger"]:
            counts[m] = sum(1 for p in result["pairs"] if p["forward"][m].get("significant", False))
        k4 = sum(1 for p in result["pairs"] if p["consensus"] >= 4)
        print(f"({dt:.1f}s) N={counts['naive_xcorr']} D={counts['diff_xcorr']} "
              f"T={counts['threshold_onset']} PG={counts['perm_granger']} "
              f"TY={counts['ty_granger']} K4={k4}")
        results[name] = result
        old = load_old_results(data_dir)
        comparisons.append(compare_results(old, result, name))

    # Save summary
    summary = {}
    for name, r in results.items():
        counts = {}
        for m in ["naive_xcorr", "diff_xcorr", "threshold_onset", "perm_granger", "ty_granger"]:
            counts[m] = sum(1 for p in r["pairs"] if p["forward"][m].get("significant", False))
        counts["k4"] = sum(1 for p in r["pairs"] if p["consensus"] >= 4)
        summary[name] = counts
    with open(os.path.join(OUTPUT_DIR, "summary.json"), 'w') as f:
        json.dump(summary, f, indent=2)

    # Write consistency check
    lines = ["# Data Consistency Check: Old (3-sigma) vs Unified (2-sigma)\n",
             f"Generated: {time.strftime('%Y-%m-%d %H:%M:%S')}\n",
             "## Parameter Changes\n",
             "| Parameter | Old (5method_leadlag) | New (unified) |",
             "|-----------|----------------------|---------------|",
             f"| threshold_sigma | 3.0 | {THRESHOLD_SIGMA} |",
             f"| xcorr_lag | 5 | {XCORR_LAG} |",
             f"| n_perm | 5000 | {N_PERM} |",
             f"| granger_lag | 1 | {GRANGER_LAG} |", "",
             "## Per-Condition Changes\n"]
    total_changes = 0
    for comp in comparisons:
        n = comp.get("n_changes", 0)
        total_changes += n
        lines.append(f"### {comp['condition']}: {n} changes")
        if n > 0:
            lines.append("")
            lines.append("| Pair | Method | Old | New | Detail |")
            lines.append("|------|--------|-----|-----|--------|")
            for ch in comp["changes"]:
                old_d, new_d = ch["old_detail"], ch["new_detail"]
                if ch["method"] == "threshold_onset":
                    detail = f"old_onset={old_d.get('canary_onset')}/{old_d.get('downstream_onset')}, new={new_d.get('canary_onset')}/{new_d.get('downstream_onset')}"
                elif "p_value" in new_d:
                    detail = f"p_old={old_d.get('p_value')}, p_new={new_d.get('p_value')}"
                else:
                    detail = ""
                lines.append(f"| {ch['pair']} | {ch['method']} | {ch['old_significant']} | {ch['new_significant']} | {detail} |")
        lines.append("")
    lines.append(f"\n## Summary\n\nTotal significance changes across all conditions: {total_changes}")
    report_path = os.path.join(BASE, "artifacts", "mmct_results", "data_consistency_check.md")
    with open(report_path, 'w') as f:
        f.write("\n".join(lines))
    print(f"\nConsistency check saved: {report_path}")
    print(f"Total time: {time.time() - t0:.1f}s")


if __name__ == "__main__":
    main()
